# Геттерлер және сеттерлер

**Геттер (getter)** - мән алу үшін есептелетін қасиет.
**Сеттер (setter)** - валидациямен мән орнату үшін әдіс.

## Синтаксис:

```dart
class MyClass {
  // Жеке өріс
  String _name;

  // Геттер
  String get name => _name;

  // Сеттер
  set name(String value) {
    if (value.isNotEmpty) {
      _name = value;
    }
  }
}
```

## Неге қажет?

1. **Деректерді тексеру** - орнатудан бұрын мәндерді тексереміз
2. **Есептелетін қасиеттер** - динамикалық есептелетін қасиеттер
3. **Инкапсуляция** - деректерге қол жеткізуді бақылаймыз
4. **Кері үйлесімділік** - интерфейсті өзгертпестен іске асыруды өзгерте аламыз

**Мысалдар →**

pages.codeSnippet:
class Rectangle {
  double _width;
  double _height;

  Rectangle(this._width, this._height);

  // Геттерлер
  double get width => _width;
  double get height => _height;

  // Есептелетін геттерлер
  double get area => _width * _height;
  double get perimeter => 2 * (_width + _height);

  // Валидациямен сеттерлер
  set width(double value) {
    if (value > 0) {
      _width = value;
    } else {
      print('Ені оң болуы керек!');
    }
  }

  set height(double value) {
    if (value > 0) {
      _height = value;
    } else {
      print('Биіктігі оң болуы керек!');
    }
  }

  void display() {
    print('Төртбұрыш:');
    print('Ені: $width, Биіктігі: $height');
    print('Ауданы: $area');
    print('Периметрі: $perimeter');
  }
}

class BankAccount {
  String _accountNumber;
  double _balance;

  BankAccount(this._accountNumber, this._balance);

  // Геттер (тек оқу)
  String get accountNumber => _accountNumber;
  double get balance => _balance;

  // Есептелетін геттер
  String get formattedBalance => '${_balance.toStringAsFixed(2)} ₸';

  // Балансты өңдеу әдістері (сеттердің орнына)
  void deposit(double amount) {
    if (amount > 0) {
      _balance += amount;
      print('Толықтырылды: $amount ₸');
    }
  }

  void withdraw(double amount) {
    if (amount > 0 && amount <= _balance) {
      _balance -= amount;
      print('Алынды: $amount ₸');
    } else {
      print('Қаражат жеткіліксіз!');
    }
  }
}

void main() {
  // Rectangle мысалы
  Rectangle rect = Rectangle(5, 10);
  rect.display();

  print('\nӨлшемдерді өзгертеміз:');
  rect.width = 8;
  rect.height = 12;
  rect.display();

  print('\nТеріс мән орнату әрекеті:');
  rect.width = -5; // валидация жұмыс істейді

  // BankAccount мысалы
  print('\n--- Банк шоты ---');
  BankAccount account = BankAccount('KZ123456789', 10000);
  print('Шот нөмірі: ${account.accountNumber}');
  print('Баланс: ${account.formattedBalance}');

  account.deposit(5000);
  print('Жаңа баланс: ${account.formattedBalance}');

  account.withdraw(3000);
  print('Жаңа баланс: ${account.formattedBalance}');

  account.withdraw(20000); // қаражат жеткіліксіз
}

