  print('Жиыны: ${bad.calculateTotal()}');
  print(bad.generateHTML());
  bad.saveToDatabase();
  bad.sendByEmail();

  print('\n=== ЖАҚСЫ ТӘСІЛ ===');
  Invoice invoice = Invoice('Б Компаниясы', 1000, ['Тауар 1', 'Тауар 2']);

  // Әр класс өз жұмысын жасайды
  InvoiceCalculator calculator = InvoiceCalculator();
