// Төлемдер үшін абстрактілі класс
abstract class PaymentMethod {
  void process(double amount);

  void printReceipt(double amount) {
    print('Сома үшін чек: $amount тг');
  }
}

// Әртүрлі төлем түрлері үшін іске асырулар
class CardPayment extends PaymentMethod {
  String cardNumber;

  CardPayment(this.cardNumber);

  @override
  void process(double amount) {
    print('\n=== Картамен төлем ===');
    print('Карта: $cardNumber');
    print('CVV тексеру...');
    print('Картадан $amount тг есептен шығару...');
    print('✓ Сәтті');
    printReceipt(amount);
  }
}

class CashPayment extends PaymentMethod {
  @override
  void process(double amount) {
    print('\n=== Қолма-қол төлем ===');
    print('$amount тг қолма-қол алынды');
    print('✓ Сәтті');
    printReceipt(amount);
  }
}

class PayPalPayment extends PaymentMethod {
  String email;

  PayPalPayment(this.email);

  @override
  void process(double amount) {
    print('\n=== PayPal арқылы төлем ===');
    print('Email: $email');
    print('PayPal-ға бағыттау...');
    print('PayPal арқылы $amount тг есептен шығару...');
    print('✓ Сәтті');
    printReceipt(amount);
  }
}

// ЖАҢА ТҮР - бар кластарды өзгертпестен қосамыз!
class BitcoinPayment extends PaymentMethod {
  String walletAddress;

  BitcoinPayment(this.walletAddress);

  @override
  void process(double amount) {
    print('\n=== Bitcoin төлемі ===');
    print('Әмиян: $walletAddress');
    print('Транзакция генерациясы...');
    print('Желі растауын күту...');
    print('✓ Сәтті');
    printReceipt(amount);
  }
}

// Кез келген төлем әдісімен жұмыс істейтін процессор
class PaymentProcessor {
  void process(PaymentMethod method, double amount) {
    method.process(amount);
  }
}

void main() {
  print('=== НАШАР ТӘСІЛ ===');
  BadPaymentProcessor bad = BadPaymentProcessor();
  bad.processPayment('card', 5000);
  print('\nBitcoin қосу? BadPaymentProcessor классын ӨЗГЕРТУ керек!');

  print('\n\n=== ЖАҚСЫ ТӘСІЛ ===');
  PaymentProcessor processor = PaymentProcessor();

  // Әртүрлі төлем әдістері
  processor.process(CardPayment('1234-5678-9012-3456'), 5000);
  processor.process(CashPayment(), 3000);
  processor.process(PayPalPayment('user@example.com'), 7000);

  // Жаңа түр қостық - Bitcoin - PaymentProcessor-ды өзгертпестен!
  processor.process(BitcoinPayment('1A1zP1eP5QGefi2DMPTfTL5SLmv7DivfNa'), 10000);

  print('\nАртықшылықтары:');
  print('✓ Bitcoin қосылғанда PaymentProcessor өзгермеді');
  print('✓ Қанша болса да жаңа төлем әдістерін қосуға болады');
  print('✓ Ескі код тұрақты қалады');
  print('✓ Әр төлем әдісін бөлек тестілеу оңай');
}

// ❌ НАШАР: Шаршы Төртбұрыштың дұрыс мұрагері емес
class BadRectangle {
  double width;
  double height;

  BadRectangle(this.width, this.height);

  double area() => width * height;
}

// Логикалы көрінеді, бірақ LSP бұзады!
class BadSquare extends BadRectangle {
  BadSquare(double side) : super(side, side);

  // Мәселе: ені орнатқанда биіктікті де орнату керек!
  set width(double value) {
    super.width = value;
    super.height = value; // Күтпеген мінез-құлық!
  }

  set height(double value) {
    super.width = value; // Күтпеген мінез-құлық!
    super.height = value;
  }
}

// ✅ ЖАҚСЫ: Дұрыс кластар иерархиясы

abstract class Shape {
  double area();
  String describe();
}

class Rectangle extends Shape {
  double width;
  double height;

  Rectangle(this.width, this.height);

  @override
  double area() => width * height;

  @override
  String describe() => 'Төртбұрыш ${width}x$height';

  void setWidth(double value) {
    width = value;
  }

  void setHeight(double value) {
    height = value;
  }
}

class Square extends Shape {
  double side;

  Square(this.side);

  @override
  double area() => side * side;

  @override
  String describe() => 'Шаршы ${side}x$side';

  void setSide(double value) {
    side = value;
  }
}

// Пішіндермен жұмыс істейтін функция
void printShapeInfo(Shape shape) {
  print('${shape.describe()}');
  print('Ауданы: ${shape.area()}');
  print('---');
}

// ❌ LSP бұзушылық мысалы
class BadBird {
  void fly() {
    print('Құс ұшады');
  }
}

// Пингвин ұша алмайды!
class Penguin extends BadBird {
  @override
  void fly() {
    throw Exception('Пингвиндер ұшпайды!'); // LSP бұзушылық!
  }
}

// ✅ ЖАҚСЫ: Дұрыс иерархия
abstract class Bird {
  void eat() {
    print('Құс тамақтанады');
  }
}

mixin Flyable {
  void fly() {
    print('Аспанда ұшады');
  }
}

class Sparrow extends Bird with Flyable {
  // Торғай ұша алады
}

class GoodPenguin extends Bird {
  // Пингвин ұша алмайды, және бұл қалыпты
  void swim() {
    print('Пингвин жүзеді');
  }
}

void main() {
  print('=== НАШАР ТӘСІЛ: Шаршы және Төртбұрыш ===');
  BadRectangle rect = BadRectangle(4, 5);
  print('Төртбұрыш ауданы: ${rect.area()}');

  BadSquare square = BadSquare(4);
  print('Шаршы ауданы: ${square.area()}');

  // Мәселе: төртбұрыш мінез-құлқын күтеміз, шаршы аламыз!
  BadRectangle shape = BadSquare(5);
  shape.width = 10; // height та өзгереді!
  print('10x5=50 күттік, алдық: ${shape.area()}'); // 100!

  print('\n=== ЖАҚСЫ ТӘСІЛ ===');
  // Барлық пішіндер базалық тип арқылы дұрыс жұмыс істейді
  List<Shape> shapes = [
    Rectangle(4, 5),
    Square(4),
    Rectangle(10, 2),
    Square(7),
  ];

  for (var shape in shapes) {
    printShapeInfo(shape); // Барлығы үшін болжамды жұмыс істейді!
  }

  print('\n=== НАШАР: Құстар ===');
  try {
    BadBird penguin = Penguin();
    penguin.fly(); // Ерекшелікпен құлайды!
  } catch (e) {
    print('Қате: $e');
  }

  print('\n=== ЖАҚСЫ: Құстар ===');
  Sparrow sparrow = Sparrow();
  sparrow.fly();

  GoodPenguin penguin = GoodPenguin();
  penguin.eat();
  penguin.swim(); // Пингвиннің өз әдістері бар

  print('\nАртықшылықтары:');
  print('✓ Мұрагерлер базалық класстан күтулерді бұзбайды');
  print('✓ Полиморфизмді қауіпсіз пайдалануға болады');
  print('✓ Күтпеген ерекшеліктер жоқ');
}

