// Менеджер жұмысшыларды басқарады
class WorkManager {
  void manageWork(Workable worker) {
    print('Жұмысты басқару:');
    worker.work();
  }

  void manageBiological(Biological living) {
    print('\nТүскі үзіліс:');
    living.eat();
  }
}

void main() {
  print('=== НАШАР ТӘСІЛ ===');
  try {
