  }

  print('\n=== ЖАҚСЫ ТӘСІЛ ===');

  Human alice = Human('Әлия');
  Robot r2d2 = Robot('R2-D2');
  Intern bob = Intern('Болат');

  WorkManager manager = WorkManager();

  // Жұмыс істей алатындардың барлығының жұмысын басқара аламыз
  manager.manageWork(alice);
  manager.manageWork(r2d2);
  manager.manageWork(bob);

  // Бірақ тек тірілер тамақтанады
  manager.manageBiological(alice);
  manager.manageBiological(bob);
  // manager.manageBiological(r2d2); // Компиляция ҚАТЕСІ - және бұл жақсы!

  print('\n=== Жалақы ===');
  alice.getSalary();
  // bob.getSalary(); // Компиляция ҚАТЕСІ - тағылымдамашы Employee емес!

  print('\n=== Зарядтау ===');
  r2d2.recharge();
  // alice.recharge(); // Компиляция ҚАТЕСІ - адам Rechargeable емес!

  print('\nАртықшылықтары:');
  print('✓ Әр класс тек қажетті әдістерді іске асырады');
  print('✓ Бос әдістер немесе ерекшеліктер жоқ');
  print('✓ Компилятор қателерден аулақ болуға көмектеседі');
  print('✓ Интерфейстер кіші және түсінікті');
}

