  @override
  void save(String data) {
    print('✓ MongoDB-ге сақталды: $data');
  }

  @override
  String load(String id) {
    return 'MongoDB-ден деректер: $id';
  }
}

// Тесттер үшін
class MockDatabase implements Database {
  @override
  void save(String data) {
    print('✓ [MOCK] Сақталды: $data');
  }

  @override
  String load(String id) {
    return '[MOCK] Тест деректері: $id';
  }
}

// Сервис абстракцияға тәуелді, нақты іске асыруға емес
class UserService {
  Database database; // Абстракцияға тәуелділік!

  // Конструктор арқылы Dependency Injection
  UserService(this.database);

  void saveUser(String name) {
    print('UserService: $name пайдаланушысын сақтау');
    database.save(name);
  }

  String getUser(String id) {
    print('UserService: $id пайдаланушысын жүктеу');
    return database.load(id);
  }
}

// Хабарламалар үшін абстракция
abstract class Notifier {
  void notify(String message);
}

class EmailNotifier implements Notifier {
  @override
  void notify(String message) {
    print('📧 Email: $message');
  }
}

class SMSNotifier implements Notifier {
  @override
  void notify(String message) {
    print('📱 SMS: $message');
  }
}

class PushNotifier implements Notifier {
  @override
  void notify(String message) {
    print('🔔 Push: $message');
  }
}

// Тіркеу сервисі абстракцияларға тәуелді
class RegistrationService {
  Database database;
  Notifier notifier;

  RegistrationService(this.database, this.notifier);

  void register(String username) {
    print('\n=== $username тіркеу ===');
    database.save('User: $username');
    notifier.notify('Қош келдіңіз, $username!');
  }
}

void main() {
  print('=== НАШАР ТӘСІЛ ===');
  BadUserService badService = BadUserService();
  badService.saveUser('Әлия');
  print('Мәселе: Кодты өзгертпестен MySQL-ді ауыстыру мүмкін емес!\n');

  print('=== ЖАҚСЫ ТӘСІЛ ===');

  // Іске асыруды оңай ауыстыра аламыз!
  print('--- MySQL ---');
  UserService service1 = UserService(MySQLDatabaseImpl());
  service1.saveUser('Әлия');
  print(service1.getUser('1'));

  print('\n--- PostgreSQL ---');
  UserService service2 = UserService(PostgreSQLDatabase());
  service2.saveUser('Болат');
  print(service2.getUser('2'));

  print('\n--- MongoDB ---');
  UserService service3 = UserService(MongoDatabase());
  service3.saveUser('Карл');

  print('\n--- Тесттер үшін Mock ---');
  UserService testService = UserService(MockDatabase());
  testService.saveUser('Тест пайдаланушы');
  print(testService.getUser('test'));

  print('\n=== ТӘУЕЛДІЛІКТЕРДІ БІРІКТІРУ ===');

  // Әртүрлі комбинациялар!
  RegistrationService reg1 = RegistrationService(
    MySQLDatabaseImpl(),
    EmailNotifier(),
  );
  reg1.register('Пайдаланушы1');

  RegistrationService reg2 = RegistrationService(
    MongoDatabase(),
    SMSNotifier(),
  );
  reg2.register('Пайдаланушы2');

  RegistrationService reg3 = RegistrationService(
    PostgreSQLDatabase(),
    PushNotifier(),
  );
  reg3.register('Пайдаланушы3');

  print('\nАртықшылықтары:');
  print('✓ MySQL-ді PostgreSQL немесе MongoDB-ге ауыстыру оңай');
  print('✓ Тестілеу үшін Mock пайдалануға болады');
  print('✓ UserService нақты ДҚ-ға тәуелді емес');
  print('✓ Әртүрлі іске асыруларды біріктіруге болады');
  print('✓ Код икемді және кеңейтімді болды');
}

