# Қателерді өңдеу

**try-catch** - бағдарламадағы қателерді (ерекшеліктерді) өңдеу механизмі.

## Синтаксис:

```dart
try {
  // Қате тудыруы мүмкін код
} catch (e) {
  // Қатені өңдеу
} finally {
  // Әрқашан орындалады (міндетті емес)
}
```

## Кеңейтілген catch:

```dart
try {
  // код
} on FormatException catch (e) {
  // Нақты қате түрін өңдеу
} on Exception catch (e, stackTrace) {
  // e - қате объектісі
  // stackTrace - стек трассировкасы
} catch (e) {
  // Қалған барлық қателерді ұстау
} finally {
  // Әрқашан орындалады
}
```

## Қате генерациясы:

```dart
throw Exception('Қате сипаттамасы');
throw FormatException('Қате формат');
throw 'Қарапайым жол-қате';
```

**Мысалдар →**

pages.codeSnippet:
import 'dart:async';

// Әртүрлі қате түрлері бар функция
Future<int> divide(int a, int b) async {
  await Future.delayed(Duration(milliseconds: 500));

  if (b == 0) {
    throw Exception('Нөлге бөлу!');
  }
  return a ~/ b;
}

Future<int> parseNumber(String text) async {
  await Future.delayed(Duration(milliseconds: 300));

  if (text.isEmpty) {
    throw FormatException('Бос жол!');
  }

  int? number = int.tryParse(text);
  if (number == null) {
    throw FormatException('"$text" сан емес');
  }

  return number;
}

Future<void> processData(String input) async {
  if (input.length < 3) {
    throw ArgumentError('Тым қысқа енгізу');
  }
  print('Өңдеу: $input');
}

void main() async {
  // Мысал 1: Базалық try-catch
  print('=== Мысал 1: Базалық try-catch ===');
  try {
    int result = await divide(10, 2);
    print('10 / 2 = $result');

    result = await divide(10, 0); // Қате!
    print('Нәтиже: $result'); // Орындалмайды
  } catch (e) {
    print('Қате: $e');
  }

  // Мысал 2: Әртүрлі қате түрлерін өңдеу
  print('\n=== Мысал 2: Әртүрлі қате түрлері ===');
  try {
    int number = await parseNumber('abc');
    print('Сан: $number');
  } on FormatException catch (e) {
    print('Формат қатесі: $e');
  } on Exception catch (e) {
    print('Басқа қате: $e');
  }

  // Мысал 3: try-catch-finally
  print('\n=== Мысал 3: finally блогы ===');
  try {
    await processData('ab'); // Тым қысқа
  } on ArgumentError catch (e) {
    print('Қате аргумент: $e');
  } finally {
    print('finally блогы орындалды');
  }

  // Мысал 4: Stack trace
  print('\n=== Мысал 4: Stack trace ===');
  try {
    await divide(5, 0);
  } catch (e, stackTrace) {
    print('Қате: $e');
    print('Stack trace:');
    print(stackTrace);
  }

  // Мысал 5: Көптік try-catch
  print('\n=== Мысал 5: Операциялар тізбегі ===');
  try {
    int num1 = await parseNumber('10');
    print('Бірінші сан: $num1');

    int num2 = await parseNumber('5');
    print('Екінші сан: $num2');

    int result = await divide(num1, num2);
    print('Нәтиже: $num1 / $num2 = $result');
  } catch (e) {
    print('Процесте қате: $e');
  } finally {
    print('Операцияны аяқтау');
  }

  // Мысал 6: Ұялаған try-catch
  print('\n=== Мысал 6: Ұялаған try-catch ===');
  try {
    try {
      await divide(10, 0);
    } catch (e) {
      print('Ішкі catch: $e');
      throw Exception('Қайталанған қате'); // Әрі қарай лақтырамыз
    }
  } catch (e) {
    print('Сыртқы catch: $e');
  }

  print('\nБағдарлама сәтті аяқталды!');
}

import 'dart:async';

// Қарапайым Stream генераторы
Stream<int> countStream(int max) async* {
  for (int i = 1; i <= max; i++) {
    await Future.delayed(Duration(milliseconds: 500));
    yield i; // Stream-ге мән жібереміз
  }
}

// Әртүрлі деректер түрлері бар Stream
Stream<String> messageStream() async* {
  yield 'Сәлем';
  await Future.delayed(Duration(seconds: 1));
  yield 'Қалай жағдай?';
  await Future.delayed(Duration(seconds: 1));
  yield 'Сау болыңыз!';
}

// Қатесі бар Stream
Stream<int> streamWithError() async* {
  yield 1;
  yield 2;
  throw Exception('Ағында қате!');
  yield 3; // Орындалмайды
}

void main() async {
  // Мысал 1: await for
  print('=== Мысал 1: await for ===');
  await for (var number in countStream(5)) {
    print('Алынды: $number');
  }
  print('Санау аяқталды');

  // Мысал 2: listen()
  print('\n=== Мысал 2: listen() ===');
  StreamSubscription subscription = countStream(3).listen(
    (number) {
      print('Оқиға: $number');
    },
    onDone: () {
      print('Stream аяқталды');
    },
    onError: (error) {
      print('Қате: $error');
    },
  );

  // Аяқталуды күтеміз
  await Future.delayed(Duration(seconds: 2));

  // Мысал 3: Деректерді түрлендіру
  print('\n=== Мысал 3: map() және where() ===');
  await for (var number in countStream(10)
      .where((n) => n % 2 == 0)  // Тек жұп
      .map((n) => n * 10)) {     // 10-ға көбейтеміз
    print('Өңделді: $number');
  }

  // Мысал 4: take()
  print('\n=== Мысал 4: take() ===');
  await for (var number in countStream(100).take(3)) {
    print('Алынды: $number'); // Тек алғашқы 3-ін алады
  }

  // Мысал 5: Stream.periodic
  print('\n=== Мысал 5: periodic ===');
  Stream<int> periodic = Stream.periodic(
    Duration(milliseconds: 300),
    (count) => count,
  ).take(5);

  await for (var tick in periodic) {
    print('Тик: $tick');
  }

  // Мысал 6: Қателерді өңдеу
  print('\n=== Мысал 6: Stream-дегі қателер ===');
  try {
    await for (var number in streamWithError()) {
      print('Сан: $number');
    }
  } catch (e) {
    print('Қате ұсталды: $e');
  }

  // Мысал 7: Жолдық Stream
  print('\n=== Мысал 7: Хабарламалар ===');
  await for (var message in messageStream()) {
    print('Хабарлама: $message');
  }

  print('\nБарлық мысалдар орындалды!');
}

import 'dart:async';

// Пайдаланушы моделі
class User {
  final String id;
  String name;
  String email;
  int age;

  User({
    required this.id,
    required this.name,
    required this.email,
    required this.age,
  });

  // Map-тен аталған конструктор (JSON үшін)
  User.fromMap(Map<String, dynamic> map)
      : id = map['id'],
        name = map['name'],
        email = map['email'],
        age = map['age'];

  // Map-ке түрлендіру (JSON үшін)
  Map<String, dynamic> toMap() {
    return {
      'id': id,
      'name': name,
      'email': email,
      'age': age,
    };
  }

  @override
  String toString() {
    return 'User(id: $id, name: $name, email: $email, age: $age)';
  }
}

// Деректермен жұмыс істеу үшін репозиторий
class UserRepository {
  // Дерекқорды симуляциялау
  final Map<String, User> _database = {};

  // Пайдаланушы жасау
  Future<User> createUser(User user) async {
    await Future.delayed(Duration(seconds: 1));
    _database[user.id] = user;
    print('✓ Пайдаланушы жасалды: ${user.name}');
    return user;
  }

  // Пайдаланушыны алу
  Future<User?> getUser(String id) async {
    await Future.delayed(Duration(milliseconds: 500));
    return _database[id];
  }

  // Барлық пайдаланушыларды алу
  Future<List<User>> getAllUsers() async {
    await Future.delayed(Duration(milliseconds: 800));
    return _database.values.toList();
  }

  // Пайдаланушыны жаңарту
  Future<User> updateUser(User user) async {
    await Future.delayed(Duration(milliseconds: 500));
    if (!_database.containsKey(user.id)) {
      throw Exception('Пайдаланушы табылмады');
    }
    _database[user.id] = user;
    print('✓ Пайдаланушы жаңартылды: ${user.name}');
    return user;
  }

  // Пайдаланушыны жою
  Future<void> deleteUser(String id) async {
    await Future.delayed(Duration(milliseconds: 500));
    _database.remove(id);
    print('✓ Пайдаланушы жойылды: $id');
  }
}

// Бизнес-логика үшін сервис
class UserService {
  final UserRepository _repository;
  final StreamController<String> _eventController = StreamController.broadcast();

  UserService(this._repository);

  // Оқиғалар Stream-і
  Stream<String> get events => _eventController.stream;

  // Пайдаланушыны тіркеу
  Future<User> registerUser(String name, String email, int age) async {
    try {
      _eventController.add('$name пайдаланушысын тіркеу...');

      // Валидация
      if (name.isEmpty) {
        throw ArgumentError('Аты бос болуы мүмкін емес');
      }
      if (!email.contains('@')) {
        throw ArgumentError('Қате email');
      }
      if (age < 0) {
        throw ArgumentError('Жасы теріс болуы мүмкін емес');
      }

      // Пайдаланушы жасау
      String id = 'user_${DateTime.now().millisecondsSinceEpoch}';
      User user = User(id: id, name: name, email: email, age: age);

      await _repository.createUser(user);
      _eventController.add('$name пайдаланушысы тіркелді');

      return user;
    } catch (e) {
      _eventController.add('Тіркеу қатесі: $e');
      rethrow;
    }
  }

  // Пайдаланушы туралы ақпарат алу
  Future<String> getUserInfo(String id) async {
    User? user = await _repository.getUser(id);
    if (user == null) {
      return 'Пайдаланушы табылмады';
    }
    return '${user.name} (${user.email}), ${user.age} жас';
  }

  // Барлық пайдаланушылар тізімі
  Future<void> listAllUsers() async {
    List<User> users = await _repository.getAllUsers();
    print('\n=== Пайдаланушылар тізімі (${users.length}) ===');
    for (var user in users) {
      print('- ${user.name} (${user.email})');
    }
  }

  void dispose() {
    _eventController.close();
  }
}

void main() async {
  // Сервис жасау
  UserRepository repository = UserRepository();
  UserService service = UserService(repository);

  // Оқиғаларға жазылу
  service.events.listen((event) {
    print('📢 Оқиға: $event');
  });

  print('=== Пайдаланушыларды басқару жүйесі ===\n');

  try {
    // Пайдаланушыларды тіркеу
    User user1 = await service.registerUser('Әлия', 'alice@example.com', 25);
    User user2 = await service.registerUser('Болат', 'bob@example.com', 30);
    User user3 = await service.registerUser('Қарл', 'carl@example.com', 28);

    // Пайдаланушылар тізімі
    await service.listAllUsers();

    // Ақпарат алу
    print('\n=== Пайдаланушы туралы ақпарат ===');
    String info = await service.getUserInfo(user1.id);
    print(info);

    // Пайдаланушыны жаңарту
    print('\n=== Жаңарту ===');
    user1.age = 26;
    await repository.updateUser(user1);

    // Жарамсыз деректермен пайдаланушы жасау әрекеті
    print('\n=== Жарамсыз тіркеу әрекеті ===');
    try {
      await service.registerUser('', 'invalid', -5);
    } catch (e) {
      print('Қате ұсталды: $e');
    }

    // Пайдаланушыны жою
    print('\n=== Жою ===');
    await repository.deleteUser(user2.id);

    // Соңғы тізім
    await service.listAllUsers();

  } catch (e) {
    print('Қате орын алды: $e');
  } finally {
    service.dispose();
    print('\nСервис тоқтатылды');
  }
}
